All predictions use only classes 0-7 and rows or columns look grouped, so I print the full tables and row/column purity to work out the hidden rules.
```python
pr=np.load('preds1500.npy')
for s in range(4):
    T=pr[s].reshape(32,32)
    rm=[np.bincount(T[i],minlength=8).argmax() for i in range(32)]; rs=[round(np.bincount(T[i],minlength=8).max()/32,2) for i in range(32)]
    cm=[np.bincount(T[:,j],minlength=8).argmax() for j in range(32)]; cs=[round(np.bincount(T[:,j],minlength=8).max()/32,2) for j in range(32)]
    print('skill',s); print(' rowmode',rm); print(' rowpure',rs); print(' colmode',cm); print(' colpure',cs)
    # additive mod8 and xor consistency: for row pairs, is difference constant across columns
    def cons(op):
        tot=[]
        for i in range(32):
            for k in range(i+1,32):
                d=op(T[i],T[k]); tot.append(np.bincount(d,minlength=8).max()/32)
        return round(float(np.mean(tot)),3)
    print(' rowpair sub8',cons(lambda x,y:(x-y)%8),'xor',cons(lambda x,y:x^y),'same',round(np.mean([(T[i]==T[k]).mean() for i in range(32) for k in range(i+1,32)]),3))
for s in [0,1,2]:
    T=pr[s].reshape(32,32); print('table',s); print('\n'.join(''.join(str(x) for x in r) for r in T))
