Skill 1 and 2 look like "row value or column value" and skill 0 looks like a monotone combination, so I test those table forms against the network's predictions (fitting a rule description, not weights); skill 3 is the null.
```python
pr=np.load('preds1500.npy'); rng=np.random.default_rng(0)
def cover(T,it=30):
    r=np.array([np.bincount(T[i],minlength=8).argmax() for i in range(32)]); c=np.array([np.bincount(T[:,j],minlength=8).argmax() for j in range(32)])
    for _ in range(it):
        for i in range(32):
            sc=[((T[i]==v)|(T[i]==c)).sum() for v in range(8)]; r[i]=int(np.argmax(sc))
        for j in range(32):
            sc=[((T[:,j]==v)|(T[:,j]==r)).sum() for v in range(8)]; c[j]=int(np.argmax(sc))
    return ((T==r[:,None])|(T==c[None,:])).mean(),r,c
res={}
for s in range(4):
    T=pr[s].reshape(32,32); cv,r,c=cover(T); res[s]=(r,c)
    M=(T==r[:,None]).astype(int)-(T==c[None,:]).astype(int)
    print('skill',s,'cover',round(cv,3),'r',r.tolist(),'c',c.tolist())
    print(' rowfrac',np.round((M>0).mean(1),2).tolist()); print(' colfrac',np.round((M<0).mean(0),2).tolist())
    # is T=op(r,c)? table of mode by (r,c)
    H=np.zeros((8,8),int); P=np.zeros((8,8))
    for u in range(8):
        for v in range(8):
            m=T[np.ix_(r==u,c==v)].ravel()
            if m.size: H[u,v]=np.bincount(m,minlength=8).argmax(); P[u,v]=(m==H[u,v]).mean()
    print(' mode table by (r,c)\n',H,'\n purity',round(P[P>0].mean(),3))
def cocl(T,k,l,rs=6):
    best=0
    for _ in range(rs):
        f=rng.integers(0,k,32); g=rng.integers(0,l,32)
        for it in range(25):
            H=np.zeros((k,l),int)
            for u in range(k):
                for v in range(l):
                    m=T[np.ix_(f==u,g==v)].ravel()
                    if m.size: H[u,v]=np.bincount(m,minlength=8).argmax()
            f=np.array([np.argmax([(H[u,g]==T[i]).sum() for u in range(k)]) for i in range(32)])
            g=np.array([np.argmax([(H[f,v]==T[:,j]).sum() for v in range(l)]) for j in range(32)])
        a=(H[f[:,None],g[None,:]]==T).mean()
        if a>best: best=a;bf,bg,bH=f.copy(),g.copy(),H.copy()
    return best,bf,bg,bH
for s in range(4):
    T=pr[s].reshape(32,32)
    print('coclust skill',s,{(k,l):round(cocl(T,k,l)[0],3) for k,l in [(2,2),(4,4),(8,8),(16,16)]})
