The (r,c) tables show skill 1 close to max(f(a),g(b)) and skill 2 close to min(f(a),g(b)); now I score many operators H(f(a),g(b)) on each skill using log-probabilities averaged over the last checkpoints to pin down f, g and skill 0's form.
```python
import pickle
def silu(x): return x/(1+np.exp(-x))
def fwd(P,X):
    h=silu(X@P['l1.weight'].T+P['l1.bias']); h=silu(h@P['l2.weight'].T+P['l2.bias']); return h@P['l3.weight'].T+P['l3.bias']
A,B=np.meshgrid(np.arange(32),np.arange(32),indexing='ij'); A=A.ravel();B=B.ravel()
def X(s):
    x=np.zeros((1024,68)); x[np.arange(1024),A]=1; x[np.arange(1024),32+B]=1; x[:,64+s]=1; return x
L=np.zeros((4,32,32,8))
for st in [1400,1425,1450,1475,1500]:
    z=np.load(f'history/step_{st:05d}.npz'); P={n:z[n] for n in NAMES}
    for s in range(4):
        lg=fwd(P,X(s))[:,:8]; lp=lg-np.log(np.exp(lg-lg.max(1,keepdims=True)).sum(1,keepdims=True))-lg.max(1,keepdims=True)
        L[s]+=lp.reshape(32,32,8)/5
np.save('L.npy',L)
u,v=np.meshgrid(np.arange(8),np.arange(8),indexing='ij')
ops={'min':np.minimum(u,v),'max':np.maximum(u,v),'add8':(u+v)%8,'sub8':(u-v)%8,'xor':u^v,'and':u&v,'or':u|v,'mul8':(u*v)%8,'mul/7':(u*v)//7,'mul/8':(u*v)//8,'absdiff':abs(u-v),'clipsum':np.minimum(u+v,7),'satsub':np.maximum(u+v-7,0),'avg':(u+v)//2,'possub':np.maximum(u-v,0)}
rng=np.random.default_rng(1)
def fit(Ls,H,rs=4,it=12):
    best=(-1e18,None,None)
    for _ in range(rs):
        f=rng.integers(0,8,32); g=rng.integers(0,8,32)
        for _i in range(it):
            for a in range(32):
                f[a]=np.argmax([Ls[a,np.arange(32),H[x,g]].sum() for x in range(8)])
            for b in range(32):
                g[b]=np.argmax([Ls[np.arange(32),b,H[f,x]].sum() for x in range(8)])
        sc=Ls[np.arange(32)[:,None],np.arange(32)[None,:],H[f[:,None],g[None,:]]].sum()
        if sc>best[0]: best=(sc,f.copy(),g.copy())
    return best
out={}
for s in range(4):
    Ls=L[s]; T=Ls.argmax(2); row=[]
    for k,H in ops.items():
        sc,f,g=fit(Ls,H,rs=2,it=8)
        ag=(H[f[:,None],g[None,:]]==T).mean(); row.append((round(ag,3),round(sc/1024,3),k)); out[(s,k)]=(f,g)
    print('skill',s,sorted(row,reverse=True)[:5])
pickle.dump(out,open('fits.pkl','wb'))
for s,k in [(1,'max'),(2,'min')]:
    print(s,k,'f',out[(s,k)][0].tolist(),'g',out[(s,k)][1].tolist())
